-- Function: public.fn_get_board_pending_teacher_handovers
-- Backup generated on 2026-10-25 20:33:03

CREATE OR REPLACE FUNCTION public.fn_get_board_pending_teacher_handovers(p_tenant_id uuid, p_org_id uuid, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(id uuid, classroom_id uuid, classroom_name character varying, shift_type character varying, outgoing_teacher_name character varying, is_critical boolean, summary_notes text, outstanding_tasks text, created_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          th.id, th.classroom_id AS classroom_id, cl.name AS classroom_name,         th.shift_type AS shift_type, th.outgoing_teacher_name AS outgoing_teacher_name,         th.is_critical AS is_critical, th.summary_notes AS summary_notes,         th.outstanding_care_tasks AS outstanding_tasks,         th.created_at AS created_at     FROM teacher_handovers th     JOIN classrooms cl ON th.classroom_id = cl.id     JOIN branches b ON th.branch_id = b.id     WHERE th.tenant_id = p_tenant_id       AND b.organization_id = p_org_id       AND th.status = 'PendingAcknowledgement'       AND (p_branch_id IS NULL OR th.branch_id = p_branch_id)       AND (p_classroom_id IS NULL OR th.classroom_id = p_classroom_id); $function$ ;
